--@ module = true
-- refinish-stockhook-install.lua
-- GENERATED by stockhook_to_rm.py from Stockhook's stockhook-install.lua: Refinish
-- Metal's built-in copy of Stockhook (Stockhook's stockhook.lua, THE
-- COPIES). Change Stockhook's file and generate again; never edit this one.
-- ==========================================
-- STOCKHOOK INSTALLER: puts the DLL where DF loads it
-- ==========================================
-- WHAT: copies the Stockhook DLL from Stockhook's folder into DF's install
-- folder as dfhooks_stockhook.dll, the first time a fort with Stockhook in
-- its load order is loaded, and again whenever the mod's copy changes (a
-- Workshop update). A copy made this session takes effect at the next
-- launch, and the prompt says so once. The player's whole install: load a
-- fort with Stockhook, restart DF once.
--
-- ACTIVE WORLDS ONLY: the scripts live in Stockhook's scripts_modactive/,
-- so nothing of Stockhook runs in a world without it (refinish-stockhook.lua, ONE
-- WORLD ONLY).
--
-- SHARED BY EVERY COPY: the standalone mod and RM's built-in copy ship the
-- same DLL and targets file, and each installer replaces DF's copies only
-- with newer ones (THE HOOK VERSION, below), so the two never swap them.
-- RM 4.1.x's installer predates that: it replaces DF's copies whenever they
-- differ from RM 4.1.x's. It runs only in a world still on RM 4.1.x, since
-- RM 4.2 is a compatible update every RM world takes.
--
-- WHY A COPY, NOT AN .INI (dfhooks, ChainLoader.cpp and LibWrapper.cpp,
-- the build DFHack 53.16-r3 ships: depends/dfhooks at 5a904e3):
--   * DF's chain-loader loads every dfhooks_*.dll in the install folder,
--     and an .ini there may instead name a DLL anywhere by its path.
--   * An .ini naming a missing file is fatal to EVERY hook library: the
--     loader calls std::filesystem::canonical on the path, which throws
--     for a missing file; the throw leaves the loader's constructor, and
--     dfhooks_init catches it with no loader at all. DFHack itself would
--     not load. Unsubscribing Stockhook would leave such an .ini pointing
--     at nothing.
--   * A copied DLL left behind after the mod is removed is harmless: with
--     no Lua side, its block stays disabled and it passes every call to
--     DF unchanged (stockhook_dll.cpp). After a DF update it hooks only a
--     build it can verify (stockhook_dll.cpp, THE AUTOMATIC TARGET).
--
-- REPLACING A LOADED DLL: Windows will not overwrite or delete a DLL that
-- is loaded, but will rename it (test 14, in play). The old copy is renamed
-- to dfhooks_stockhook.dll.old, or .old1 to .old9 when an earlier one is
-- still held (SET-ASIDE NAMES; the loader takes only .dll and .ini, so all
-- are ignored), and the new one written in its place; set-aside copies are
-- deleted at a later run, once nothing holds them.
--
-- THE TARGETS FILE: stockhook_targets.txt, the DF builds the DLL may hook
-- (stockhook_dll.cpp, THE TARGETS). The DLL reads it from DF's folder at
-- launch. A build not listed is hooked only if the DLL verifies it (THE
-- AUTOMATIC TARGET there), so after a DF update a new line in the mod's
-- copy, shipped as a Workshop update, is needed only when the checks refuse
-- the build: this file copies it beside the DLL like the DLL itself. Plain text,
-- never held open, so it is simply overwritten.
--
-- WHERE THE MOD'S COPY IS: next to this mod's info.txt, found from this
-- script's own path (dfhack.findScript): <mod>/scripts_modactive/this
-- file.
-- That works wherever DF keeps the mod (the Workshop folder, mods/,
-- data/installed_mods/).
--
-- COMMANDS (through refinish-stockhook.lua): refinish-stockhook install, refinish-stockhook uninstall.
--
-- THE FALLBACK PROMPT (2026-11-09): at the fort load, when Stockhook's
-- hook is not live and no restart is pending, the prompt tells the player
-- (refinish-stockhook.lua, THE PROMPT: RM's prompt in a world with RM, DFHack's own
-- message box otherwise). See the section of that name.
--
-- API: check(popup), uninstall()

local DLL_NAME = 'dfhooks_stockhook.dll'
local TARGETS_NAME = 'stockhook_targets.txt'

-- ---- THE HOOK VERSION ----
-- One number for the DLL and targets file this copy ships. RAISE IT
-- WHENEVER EITHER FILE CHANGES, in the same release; stockhook_to_rm.py
-- carries it into RM's copy with everything else. The installer writes the
-- number of the files it put in DF's folder to VERSION_NAME there, and
-- compares it with this copy's at every check:
--   * DF's number higher: another copy (the standalone, or a newer RM)
--     installed newer files. They are left alone: an older copy never puts
--     its files back over newer ones.
--   * the same number: the files are replaced only if they differ (a file
--     damaged, or put back by RM 4.1.x's installer).
--   * lower, or no number (nothing installed yet, or installed by RM 4.1.x,
--     which writes none): the files are installed or updated when they
--     differ, as before.
-- Version 1: RM 4.1.6's DLL and targets file, byte for byte (layout 6, DF
-- 53.16 and 53.17 listed).
local HOOK_VERSION = 1
local VERSION_NAME = 'stockhook_version.txt'

-- Everything this mod keeps on _G (refinish-stockhook.lua, EVERYTHING ON _G, IN ONE
-- TABLE): install_checked and fallback_said here.
_G.refinish_stockhook_mod = _G.refinish_stockhook_mod or {}
local G = _G.refinish_stockhook_mod

-- ---- THE LOG ----
-- Through refinish-stockhook.lua's log (THE LOG there): no console prints. Looked
-- up per call: this file loads beside it.
local function log_line(msg, typ)
    local ok, sh = pcall(reqscript, 'refinish-stockhook')
    if ok and sh and sh.log then sh.log(typ or 'INFO', msg, 'INSTALL') end
end

-- refinish-stockhook.lua itself, or nil.
local function core()
    local ok, sh = pcall(reqscript, 'refinish-stockhook')
    if ok and type(sh) == 'table' then return sh end
    return nil
end

-- ==========================================
-- PATHS
-- ==========================================
local function as_dir(p)
    p = tostring(p or ''):gsub('\\', '/')
    if p ~= '' and p:sub(-1) ~= '/' then p = p .. '/' end
    return p
end

-- The mod's own copy: <mod>/dfhooks_stockhook.dll, two folders up from
-- this script. nil when this script is not on the script path (the mod is
-- not active in this world).
-- name: the file in the mod's root, DLL_NAME unless another is asked for.
local function source_path(name)
    local me = dfhack.findScript('refinish-stockhook-install')
    if not me then return nil end
    me = me:gsub('\\', '/')
    local mod_root = me:match('^(.*)/scripts_modactive/[^/]+$')
    if not mod_root then return nil end
    return mod_root .. '/' .. (name or DLL_NAME)
end

local function target_path(name)
    return as_dir(dfhack.filesystem.getInstallDir()) .. (name or DLL_NAME)
end

-- ==========================================
-- FILES
-- ==========================================
local function read_all(path)
    local f = io.open(path, 'rb')
    if not f then return nil end
    local data = f:read('*a')
    f:close()
    return data
end

local function write_all(path, data)
    local f, err = io.open(path, 'wb')
    if not f then return false, err end
    local ok, werr = f:write(data)
    f:close()
    if not ok then return false, werr end
    return true
end

-- DF's folder's hook version (THE HOOK VERSION), or nil when it has none.
local function read_version()
    local f = io.open(target_path(VERSION_NAME), 'r')
    if not f then return nil end
    local n = tonumber((f:read('*l') or ''):match('%d+'))
    f:close()
    return n
end

-- Records this copy's version once DF's folder holds its files. had: the
-- number read at the start of the check, so an unchanged number is not
-- written again.
local function note_version(had)
    if had == HOOK_VERSION then return end
    local ok, err = write_all(target_path(VERSION_NAME), tostring(HOOK_VERSION) .. '\n')
    if not ok then
        log_line('install: could not write ' .. VERSION_NAME .. ': ' .. tostring(err), 'WARNING')
    end
end

-- ==========================================
-- SET-ASIDE NAMES
-- ==========================================
-- A DLL moved aside goes to the first free name of .old, .old1 ... .old9.
-- Several may be needed in one session: a copy renamed earlier in the
-- session is still loaded, cannot be deleted, and blocks its name (test 14:
-- the update at map load took .old, then uninstall's rename onto .old failed
-- with "File exists"). The loader takes only .dll and .ini, so every one of
-- these is ignored, and each is deleted once nothing holds it.
local ASIDE = { '.old' }
for i = 1, 9 do ASIDE[#ASIDE + 1] = '.old' .. i end

-- Deletes every set-aside copy nothing holds any more. One still loaded
-- this session fails quietly and is tried again at a later run.
local function clear_aside()
    local dst = target_path()
    for _, ext in ipairs(ASIDE) do os.remove(dst .. ext) end
end

-- Renames the installed DLL to the first free set-aside name. Returns that
-- path, or nil and why.
local function move_aside()
    local dst = target_path()
    clear_aside()
    for _, ext in ipairs(ASIDE) do
        if not dfhack.filesystem.exists(dst .. ext) then
            local ok, err = os.rename(dst, dst .. ext)
            if ok then return dst .. ext end
            return nil, tostring(err)
        end
    end
    return nil, 'every set-aside name is taken; restart DF and try again'
end

-- ==========================================
-- THE RESTART PROMPT
-- ==========================================
-- Through refinish-stockhook.lua's prompt (THE PROMPT there). "Restart" alone read
-- as "back to the title screen" (test 14): DF loads hook DLLs only when
-- the program starts, so the text says to close DF completely. Until the
-- restart, RM's own stockpile system runs in a world with RM; in any other
-- world Stockhook's rows sort nothing. what: 'installed' or 'updated'.
local function restart_prompt(what)
    local sh = core()
    if not sh or not sh.prompt then
        log_line('install: the restart prompt could not be shown (refinish-stockhook.lua not found).', 'ERROR')
        return
    end
    local until_then = sh.rm_world() and ' Until the restart, piles use the old stockpiling system.'
        or " Until the restart, the stockpile rows Stockhook adds sort nothing."
    local ok, shown = pcall(sh.prompt, ('Stockhook was %s. Close Dwarf Fortress completely and start'
        .. ' it again to finish.'):format(what) .. until_then, nil, 12)
    if not (ok and shown) then
        log_line('install: the restart prompt failed: ' .. tostring(shown), 'ERROR')
    end
end

-- ==========================================
-- THE TARGETS FILE: copied when the copies differ
-- ==========================================
-- Returns true when it was written this run. A mod without the file
-- writes nothing: the DLL's built-in build stays the only one.
local function check_targets()
    local src = source_path(TARGETS_NAME)
    local new = src and read_all(src)
    if not new or #new == 0 then return false end
    local dst = target_path(TARGETS_NAME)
    if read_all(dst) == new then return false end
    local ok, err = write_all(dst, new)
    if not ok then
        log_line('install: could not write ' .. dst .. ': ' .. tostring(err))
        return false
    end
    log_line('install: ' .. TARGETS_NAME .. ' written at ' .. dst .. '; read at the next launch')
    return true
end

-- ==========================================
-- CHECK: install or update when the copies differ
-- ==========================================
-- Returns 'current', 'installed', 'updated', or nil and why. popup: show
-- the restart prompt when the DLL changed this session.
function check(popup)
    -- Copies set aside earlier are free to go once nothing holds them.
    clear_aside()

    local src = source_path()
    if not src then return nil, 'Stockhook not active in this world' end
    local new = read_all(src)
    if not new or #new == 0 then
        log_line('install: no ' .. DLL_NAME .. ' in the mod folder (' .. src .. ')')
        return nil, 'no DLL in the mod folder'
    end

    -- ---- NEWER FILES ARE LEFT ALONE (THE HOOK VERSION) ----
    local had = read_version()
    if had and had > HOOK_VERSION then
        log_line(("install: DF's folder holds hook version %d, newer than this copy's %d; left"
            .. ' alone.'):format(had, HOOK_VERSION))
        return 'newer'
    end

    -- The targets file first: a new DF build listed needs the same restart
    -- as a new DLL.
    local targets_new = check_targets()

    local dst = target_path()
    local old = read_all(dst)
    if old == new then
        note_version(had)
        if targets_new and popup then restart_prompt('updated') end
        return targets_new and 'updated' or 'current'
    end

    -- ---- MOVE THE OLD COPY ASIDE ----
    -- A loaded DLL can be renamed but not overwritten (test 14: renamed
    -- while loaded, in play).
    local aside = nil
    if old then
        local err
        aside, err = move_aside()
        if not aside then
            log_line('install: could not move the old DLL aside: ' .. tostring(err))
            return nil, 'old DLL not renamable: ' .. tostring(err)
        end
    end

    -- ---- WRITE THE NEW ONE ----
    -- Written under a temporary name first, so a failed write never leaves
    -- a truncated dfhooks_stockhook.dll for the loader to find.
    local tmp = dst .. '.new'
    local ok, err = write_all(tmp, new)
    if ok then ok, err = os.rename(tmp, dst) end
    if not ok then
        os.remove(tmp)
        if aside then os.rename(aside, dst) end   -- put the old one back
        log_line('install: could not write ' .. dst .. ': ' .. tostring(err))
        return nil, 'install folder not writable'
    end

    note_version(had)
    local what = old and 'updated' or 'installed'
    log_line(('install: DLL %s at %s; takes effect at the next launch'):format(what, dst))
    if popup then restart_prompt(what) end
    return what
end

-- ==========================================
-- UNINSTALL
-- ==========================================
-- The DLL is moved to a set-aside name (deleted at a later run of check,
-- or by the player once DF is closed). From the next launch DF no longer
-- loads it.
function uninstall()
    local dst = target_path()
    if not dfhack.filesystem.isfile(dst) then return false, 'not installed' end
    local aside, err = move_aside()
    if not aside then return false, err end
    os.remove(target_path(VERSION_NAME))      -- THE HOOK VERSION: nothing installed now
    log_line('uninstall: DLL moved to ' .. aside .. '; not loaded from the next launch')
    return true
end

-- ==========================================
-- THE FALLBACK PROMPT (2026-11-09)
-- ==========================================
-- When Stockhook's hook is not live at a fort load, the player is told so
-- then, at the load, not left to find out in play that Stockhook's rows
-- sort nothing. In a world with Refinish Metal, RM's own stockpile system
-- runs instead (RM's refinish-stockpile-windows.lua, which asks from its
-- loop, a loop that does not run paused: before this the only sign was a
-- WARNING in RM's log once the game was unpaused). In any other world
-- piles work as DF makes them.
-- Once a session. Not shown:
--   * when this load already asks for a restart (installed or updated):
--     the hook comes up at the next launch;
--   * for stockhook.disable: the player switched it off.
-- A hook live on a DF build nobody listed (stockhook_dll.cpp, THE
-- AUTOMATIC TARGET) is said in the log at INFO: nothing for the player
-- to do, but it tells a maintainer the build can be listed.
-- RISK_M (light red) is RM's theme colour for something broken that the
-- player will notice and can carry on past; DFHack's message box takes
-- light red for it.
local function fallback_check()
    if G.fallback_said then return end
    local sh = core()
    if not sh or not sh.available then return end
    G.fallback_said = true
    local live, why = sh.available()
    if live then
        local st = sh.stats and sh.stats()
        if st and st.automatic == 1 then
            log_line('live on a DF build not listed in ' .. TARGETS_NAME .. ": the DLL verified it"
                .. " and hooked it. stockhook.log, in DF's folder, holds the line that lists it.")
        end
        return
    end
    why = tostring(why)
    if why:find('stockhook.disable', 1, true) then
        log_line('not live: stockhook.disable is present, so no prompt.')
        return
    end
    log_line('not live at the fort load: ' .. why, 'WARNING')
    local text
    if why:find('block layout', 1, true) then
        -- THE HOOK VERSION: DF's folder holds another version's DLL, whose
        -- shared block this copy cannot read.
        local which = (sh.copy_mod and sh.copy_mod() == 'stockhook') and 'Stockhook' or 'Refinish Metal'
        text = "The Stockhook files in Dwarf Fortress's folder are a different version from the"
            .. " copy of Stockhook in this world, so the stockpile rows it adds sort nothing here."
            .. (sh.rm_world() and " Refinish Metal's older stockpile system is running instead." or '')
            .. ' Updating ' .. which .. ' should fix this. The reason is in ' .. sh.log_file()
            .. ", in DF's folder."
    elseif sh.rm_world() then
        text = "Stockhook is not working with this version of Dwarf Fortress, so Refinish Metal's"
            .. " older stockpile system is running instead. Stockpiles still work, but the extra"
            .. " stockpile rows Stockhook adds sort nothing until Stockhook is updated. The reason"
            .. " is in " .. sh.log_file() .. ", in DF's folder."
    else
        text = "Stockhook is not working with this version of Dwarf Fortress, so the stockpile rows"
            .. " it adds sort nothing until Stockhook is updated. Stockpiles still work as Dwarf"
            .. " Fortress makes them. The reason is in " .. sh.log_file() .. ", in DF's folder."
    end
    local okp, shown = pcall(sh.prompt, text, 'RISK_M', 14)
    if not (okp and shown) then log_line('the fallback prompt failed: ' .. tostring(shown), 'ERROR') end
end

-- ==========================================
-- MAP LOAD: check once a map is up
-- ==========================================
-- Map load rather than script load, so the prompt has a screen to show on.
-- Once a session: a copy made earlier this session is already in place.
-- Only in a world with Stockhook in its load order: the handler stays for
-- the session once registered (refinish-stockhook.lua, ONE WORLD ONLY). Its name is
-- this copy's own, never another copy's (refinish-stockhook.lua, THE COPIES).
local function world_active()
    local ok, active = pcall(function() return reqscript('refinish-stockhook').world_active() end)
    return ok and active
end

if dfhack_flags and dfhack_flags.module then
    dfhack.onStateChange['refinish_stockhook:install'] = function(code)
        if code == SC_MAP_LOADED and not G.install_checked and world_active() then
            dfhack.timeout(1, 'frames', function()
                if G.install_checked then return end
                local ok, what, why = pcall(check, true)
                if not ok then
                    log_line('install: ' .. tostring(what))
                elseif what then
                    G.install_checked = true
                else
                    log_line('install: not done: ' .. tostring(why))
                end
                -- THE FALLBACK PROMPT, unless this load asks for a restart.
                if not (ok and (what == 'installed' or what == 'updated')) then
                    local okf, err = pcall(fallback_check)
                    if not okf then log_line('fallback check failed: ' .. tostring(err), 'ERROR') end
                end
            end)
        end
    end
end
